//! 🧬️ SemioTableMutation — document mutation dispatch. Semantic vocabulary derived from
//! `📸️snapshot/🦀️.rs`'s `SemioTableSnapshot` shape (a name-keyed `columns` collection
//! plus an index-keyed, id-less `rows` collection whose `cells` are POSITIONALLY ALIGNED with
//! `columns`) per `../SEMANTIC-MUTATIONS-OVERHAUL/📓️taxonomy.md`/`📓️derivation-rules.md`. `impl
//! protocol::Mutation`/`SemanticMutation` below are generated by `#[derive(dsl::Mutations)]` —
//! never hand-written.
//!
//! `columns: Vec<SemioTableColumn>` is name-keyed (`📓️taxonomy.md` addressing rule #2 — like cad
//! layers/xlsx sheets): `create-column`/`delete-column`/`rename-column`/`reorder-columns` address
//! by `name`. `rows: Vec<SemioTableRow>` has no stable id (addressing rule #3): `insert-row`/
//! `remove-row` address by index (inserted = FINAL-state, removed = BASE-state), `reorder-rows`
//! moves one row within the sequence, `edit-cell` replaces one cell's authored value addressed by
//! `{row_index, column_name}`. Every column insert/remove/reorder applies the IDENTICAL
//! insert/remove/reorder, at the IDENTICAL index, to every row's `cells` — the CRITICAL alignment
//! invariant documented on `SemioTableSnapshot` itself.
//!
//! Every triad leaf is mounted directly as a `mutations`-sibling module in `🦀️.rs` (the stdio
//! W2 agent owns `🦀️.rs`, so no self-wiring `#[path = "."]` blocks are needed here).

use crate::standards::v1::subsets::table::schema::diff::SemioTableDiff;
use crate::standards::v1::subsets::table::schema::snapshot::SemioTableSnapshot;

//#region 🔖️Leaves
use super::create_column;
use super::delete_column;
use super::edit_cell;
use super::insert_row;
use super::remove_row;
use super::rename_column;
use super::reorder_columns;
use super::reorder_rows;
//#endregion 🔖️Leaves

//#region 🔖️Mutations
/// 🧬️ Every variant wraps exactly one `protocol::MutationKind<SemioTableSnapshot,
/// SemioTableMutation>` payload struct declared in the corresponding triad leaf's
/// `🦠️mutation/🦀️.rs`. This plugin crate reaches the derive through the `dsl` extern-crate
/// alias `🦀️.rs` declares (`extern crate semio_framework_os_kernel as dsl;`), the same spelling
/// `🔤️text`'s already-compiling facet uses.

#[derive(Clone, Debug, PartialEq, value_derive::ToValue, value_derive::FromValue, dsl::Mutations, semio_framework_value::CanonicalJsonTree)]
#[canonical_json(owner = semio_framework_pack_json)]
#[mutations(snapshot = SemioTableSnapshot, diff = SemioTableDiff, schema = "s.stdio.semio.table")]
pub enum SemioTableMutation {
    CreateColumn(create_column::CreateColumn),
    DeleteColumn(delete_column::DeleteColumn),
    RenameColumn(rename_column::RenameColumn),
    ReorderColumns(reorder_columns::ReorderColumns),
    InsertRow(insert_row::InsertRow),
    RemoveRow(remove_row::RemoveRow),
    ReorderRows(reorder_rows::ReorderRows),
    EditCell(edit_cell::EditCell),
}

/// 🏷️ Kebab-case spelling of every `SemioTableMutation` variant, in declaration order — the
/// vocabulary the `semio-v1-table` mutation catalog (`../../🔣️oracle.json`) declares and
/// `📊️mutate-semio-table`'s exhaustive test case measures itself against. `kinds_match_the_enum_and_
/// the_catalog` below is what keeps this list honest against the enum, since the framework never
/// parses Rust.
pub const KINDS: &[&str] = &["create-column", "delete-column", "rename-column", "reorder-columns", "insert-row", "remove-row", "reorder-rows", "edit-cell"];
//#endregion 🔖️Mutations

/// 🧮️ Pure diff face of [`Mutation::diff`], named only in this subset's own reachable types (`protocol` is a private
/// `extern crate` alias, so an owner-root test adapter cannot bring the `Mutation` trait into scope).
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
pub fn diff_semio_table_mutation(mutation: &SemioTableMutation, base: &SemioTableSnapshot) -> protocol::MutationOutcome<SemioTableDiff> {
    <SemioTableMutation as protocol::Mutation<SemioTableSnapshot>>::diff(mutation, base)
}


/// ↩️ Computes `mutation`'s own inverse against `base` — a thin wrapper around
/// `protocol::Mutation::inverse` so external Rust callers that cannot name this crate's private
/// `protocol` extern-crate item (the `📊️mutate-semio-table` test adapter, whose `inverse-<kind>` scenarios
/// need a mutation's own computed inverse) can still reach the inverse law that
/// `diff_semio_*_mutation` alone cannot. Same shape as `🧰️kit`'s `inverse_semio_kit_mutation`.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
pub fn inverse_semio_table_mutation(mutation: &SemioTableMutation, base: &SemioTableSnapshot) -> Result<Vec<SemioTableMutation>, semio_framework_value::ValueError> {
    Ok({
    use protocol::Mutation;
    <SemioTableMutation as Mutation<SemioTableSnapshot>>::inverse(mutation, base)?

    })
}


//#endregion 🔖️Apply

